import{_ as r,l,o as a,c as o,v as t,p as E,x as i,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"信号发送","description":"","frontmatter":{"title":"信号发送","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/spence-signaling.md","filePath":"econ/spence-signaling.md","lastUpdated":1789023840000}'),B={name:"econ/spence-signaling.md"};function d(h,e,A,_,m,u){const n=l("Mermaid");return a(),o("div",null,[e[1]||(e[1]=t('<h1 id="信号发送" tabindex="-1">信号发送 <a class="header-anchor" href="#信号发送" aria-label="Permalink to &quot;信号发送&quot;">​</a></h1><div class="epigraph"><p>若发信号的成本对高生产率者更低，教育可以在均衡中分离类型，即使教育本身不提高产出。</p><footer>—— Spence, Job Market Signaling, QJE, 1973</footer></div><p><a href="/econ/unraveling-lemons">上一课</a>（逐级退出）。里买方只看见价格，好车无法把自己摘出来。缺口是知情者先动：选一个有成本的可观察行动，让接收者的<a href="/econ/perfect-bayesian">信念</a>在路径上退化到真类型。Spence 把行动读成教育年限，类型读成生产率。本课钉分离的单交叉与混同的脆弱，不把菜单设计写成筛选。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>类型 \\(\\theta\\in\\{H,L\\}\\)，信号 \\(e\\ge 0\\)，成本 \\(c(e,\\theta)\\)，且 \\(c_e(e,L)\\gt c_e(e,H)\\)（单交叉 / Spence–Mirrlees）。接收者看见 \\(e\\)，付工资等于该后验下的期望产出。分离均衡：\\(\\theta\\) 选不同的 \\(e\\)，工资等于真产出。低类型模仿高类型的代价，必须大于工资差；高类型宁可付自己的信号成本，也不愿被当成低类型。</p><p>关键：教育可以完全是浪费的社会成本，只要成本差能排序类型。分离把柠檬里被切断的互利交易救回来，代价是烧信号。混同：大家都选同一 \\(e\\)，工资等于平均产出；要挡住高类型用别的 \\(e\\) 跳出去，路径外信念往往得把偏离判给低类型——这正是 PBE 过松之处。</p><h3 id="信号不是筛选" tabindex="-1">信号不是筛选 <a class="header-anchor" href="#信号不是筛选" aria-label="Permalink to &quot;信号不是筛选&quot;">​</a></h3><p>信号是知情者先动、自选成本。筛选是不知情者先出合同菜单，让类型自己对号。时序决定信息租金归谁、有没有浪费的信号。下一课换时序。</p><p><span class="marginnote">工资等于期望产出，来自买方竞争。若买方有市场力，工资低于产出，分离条件改写，但单交叉仍是分离的引擎。Riley 反应均衡、直觉标准通常删掉「浪费最多」的混同，留下最小成本分离。</span></p><p>单交叉写的是边际成本排序，不是总成本排序。 总成本也可以对高类型更低，但分离要的是「多发一单位信号」对谁更便宜。 没有单交叉，分离 IC 可以无解，市场退回柠檬。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：两类型、连续信号、竞争性接收者。先写分离：低类型选其完全信息最优（常是 \\(e=0\\)），高类型选使低类型无差异的最低 \\(e^*\\)。再写混同：共同 \\(e\\)，检查高类型是否想偏离到能被当成高类型的 \\(e&#39;\\)；若路径外把 \\(e&#39;\\) 判给低类型，混同可被撑住。用直觉标准：低类型更不想发 \\(e&#39;\\) 时，不应把 \\(e&#39;\\) 判给他，混同垮。</p>',12)),(a(),E(c,null,{default:i(()=>[p(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEM%5B%22%E6%9F%A0%E6%AA%AC%EF%BC%9A%E5%8F%AA%E6%9C%89%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20SIG%5B%22%E7%9F%A5%E6%83%85%E8%80%85%E5%85%88%E9%80%89%20e%22%5D%0A%20%20SC%5B%22%E5%8D%95%E4%BA%A4%E5%8F%89%EF%BC%9A%E9%AB%98%E7%B1%BB%E5%9E%8B%E4%BF%A1%E5%8F%B7%E6%9B%B4%E4%BE%BF%E5%AE%9C%22%5D%20--%3E%20SEP%5B%22%E5%88%86%E7%A6%BB%EF%BC%9A%E5%B7%A5%E8%B5%84%20%3D%20%E7%9C%9F%E4%BA%A7%E5%87%BA%22%5D%0A%20%20SIG%20--%3E%20SC%0A%20%20SIG%20--%3E%20POOL%5B%22%E6%B7%B7%E5%90%8C%EF%BC%9A%E9%9D%A0%E8%B7%AF%E5%BE%84%E5%A4%96%E4%BF%A1%E5%BF%B5%22%5D%0A%20%20POOL%20--%3E%20REF%5B%22%E7%B2%BE%E7%82%BC%E5%B8%B8%E5%88%A0%E6%B7%B7%E5%90%8C%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>单交叉让无差异曲线只交一次，高类型能用「多一点 \\(e\\)」换「被当成高」而低类型觉得不划算。这是激励相容的几何，不是教育生产函数。社会看，\\(e\\) 的资源耗尽可以是纯耗散；私人看，它买到了正确的信念。最小成本分离把耗散压到刚好挡住低类型，再高的 \\(e\\) 也是分离 PBE，但更浪费，精炼通常不要。</p><p>与柠檬对比：好车若能烧一笔对柠檬更痛的鉴定费，就能分离。若鉴定费对两类一样痛，单交叉失败，信号帮不上，市场仍可能萎缩。知情者先动意味着耗散成本由发送者承担；下一课不知情者先出菜单，耗散变成对低类型数量的扭曲，租金留给高类型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多于两类型，分离的 \\(e(\\theta)\\) 由微分方程钉住，仍靠单交叉。信号若同时提高产出（人力资本），分离与生产纠缠，实证难分。多个接收者、逆向选择加信号，均衡可以不存在（Rothschild–Stiglitz 在保险筛选侧更突出）。廉价空谈（cheap talk）成本为零，单交叉谈不上，要另用 Crawford–Sobel，不在本课。</p><p>连续类型时分离的 \\(e(\\theta)\\) 由绑定的局部 IC 微分方程决定，仍是单交叉在起作用。本课两类型已经够把时序钉住。</p><p>后课默认：知情者先动、有成本信号、单交叉，则最小成本分离是基准 PBE；混同依赖怪信念。不知情者先动则换成筛选与信息租金。</p><h3 id="分离有很多-精炼留下最小成本" tabindex="-1">分离有很多，精炼留下最小成本 <a class="header-anchor" href="#分离有很多-精炼留下最小成本" aria-label="Permalink to &quot;分离有很多，精炼留下最小成本&quot;">​</a></h3><p>分离 PBE 有很多：高类型可以发比挡住低类型更高的 \\(e\\)。精炼通常只留下最小成本那一个：低类型选完全信息最优（常是 \\(e=0\\)），高类型选使低类型无差异的最低 \\(e^*\\)。工资差是奖，成本差是障碍。筛选没有这笔烧钱的 \\(e\\)，扭曲写在低类型数量上。人力资本若同时提高产出，信号与生产缠在一起，实证难分；本课允许 \\(e\\) 纯浪费，好把机制看清。</p><p>教育若被管制成同一强制 \\(e\\)，分离维度被毁掉，回到柠檬平均。文凭通胀则是人人提高 \\(e\\) 仍混同，相对位置才传递信息。</p><p><span class="marginnote">单交叉：无差异曲线只交一次，「更高的 \\(e\\)」才能排序类型。成本差反了，分离方向会翻或失败。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>知情者先动，用成本差分离类型；教育可以不提高产出。</li><li>单交叉是分离的关键条件。</li><li>混同比分离更依赖路径外信念，精炼常留下最小成本分离。</li><li>时序一换，问题变成筛选。</li><li>出处：Spence, <em>QJE</em> 1973。</li></ul>',13))])}const C=r(B,[["render",d]]);export{S as __pageData,C as default};
